from dataclasses import dataclass
from functools import cached_property
import sympy as sp


@dataclass(frozen=True)
class Task:
    data: dict

    @cached_property
    def symbols(self):return sp.symbols('s y dy',real=True)
    @cached_property
    def expression(self):
        # Task files are generated by the symbolic manager, not arbitrary code.
        from symbolic_input import Expressions
        return Expressions(('s','y','dy'),()).read(self.data['residual'])
    @property
    def interval(self):return tuple(float(sp.Rational(v)) for v in self.data['interval'])
    @property
    def trace(self):return float(sp.Rational(self.data['initial']))
    @property
    def critical(self):return self.data['operator']=='BB'
    def numpy_functions(self):
        s,y,dy=self.symbols
        return tuple(sp.lambdify((s,y,dy),e,'numpy') for e in (self.expression,self.expression.diff(y),self.expression.diff(dy)))
    def torch_function(self):
        # Polynomial/rational expressions use tensor arithmetic; algebraic constants are numeric.
        return sp.lambdify(self.symbols,sp.N(self.expression,17),modules=[{}])
